WITH src AS (SELECT * FROM order_items WHERE product_id IN (9, 38) AND (order_id IN (1, 14, 18, 37) OR order_id IN (7, 11, 29, 37))), summary AS (SELECT CASE WHEN unit_price >= 380 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MIN(quantity) AS min_quantity FROM src GROUP BY CASE WHEN unit_price >= 380 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END) SELECT * FROM summary ORDER BY unit_price_bucket
